-- Framing notes:
--   ★★★ THE LAW WRITTEN ON THE HEART (THREAD 4, KEYSTONE): *I will run the way of thy commandments, when thou
--      shalt enlarge my heart* (v.32) + *Incline my heart unto thy testimonies* (v.36) is the prayer Jeremiah
--      31:33 and Ezekiel 36:26-27 answer — the Torah put in the inward parts, the new heart that WALKS in the
--      statutes. The new covenant is the SAME Torah on the heart, never the Torah abolished. 2 Cor 3:3 names
--      the fleshy tables. Sirach 24:23 seals it: the wisdom that dwells in Jacob IS the book of the covenant,
--      the law Moses commanded.
--   ★★ THE WORD SETTLED FOR EVER (THREAD 6): *For ever, O Yahuah, thy word is settled in heaven* (v.89) /
--      *thy word is true from the beginning: and every one of thy righteous judgments endureth for ever* (v.160)
--      is the anti-antinomian keystone — answered by *one jot or one tittle shall in no wise pass from the law*
--      (Matt 5:18), Isa 40:8, 1 Pet 1:25, Ps 111:7-8, and Baruch 4:1 (the law that endureth for ever).
--   ★★ THE PERFECT LAW OF LIBERTY (THREAD 5): *I will walk at liberty: for I seek thy precepts* (v.45) overturns
--      the antinomian inversion — freedom IS Torah-keeping (James 1:25; 2:12; John 8:31-32,36, where the truth
--      that frees is His word continued in).
--   ★★ THE VAIL DONE AWAY, NOT THE LAW (THREAD 3): *Open thou mine eyes, that I may behold wondrous things out
--      of thy law* (v.18) — 2 Cor 3:14-16 is read EXACTLY: it is the VAIL on the reading that is done away in
--      Messiah, never the law itself; the Spirit opens the eyes (Luke 24:45) to the same Torah.
--   ★★★ THE LOST SHEEP STILL HOLDING THE COMMANDMENTS (THREAD 11): the 176-verse Torah-lover closes *I have
--      gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (v.176) — Isaiah
--      53:6 (all we like sheep), the two-house Shepherd who seeks His sheep (Ezek 34:11-16), the lost sheep
--      sought and carried home (Luke 15:4-6). The delight in Torah and the confession of straying stand together.
--   1 JOHN 2:3-4 FILTER: surfaced at THREAD 1 — to know Him is to keep His commandments; the whole acrostic
--      is the living proof that the covenant-word is the delight of the heart, not a defunct old covenant.
--   VERSES WITH NO SEPARATE ADD: the persecution/affliction petitions (vv.21-23,42,51,61,69,78,84-87,95,
--      110,121-122,134,139,150,153-158,161), the "quicken me" pleas (vv.25,37,40,88,107,149,154,156,159), and
--      the stanza-acrostic refrains are recorded as folded — they reinforce the twelve framework-bearing themes
--      (delight, the word hid, the eyes opened, the heart enlarged, liberty, the eternal word, love, the lamp,
--      truth, peace, the lost sheep, the affliction that teaches) rather than warranting independent threads.

CREATE TEMP VIEW _s302_ps119_lookup AS
SELECT e.slug AS edition_slug, b.slug AS book_slug, c.chapter_number, v.verse_number, v.id AS verse_id
  FROM verses v JOIN chapters c ON v.chapter_id=c.id JOIN books b ON c.book_id=b.id
  JOIN editions e ON b.edition_id=e.id
 WHERE e.slug IN ('canon','enoch','jubilees','jasher','apocrypha','apocrypha-charles-vol1','pseudepigrapha','adam-eve-conflict','apocalypse-of-abraham','ascension-isaiah','sonnini-acts-29');

INSERT INTO cross_references (source_verse_id, target_verse_id, source, note, tier_required)
SELECT sv.verse_id, tv.verse_id, 'manual', i.note, i.tier::content_tier
  FROM (VALUES
    -- THREAD 1: Blessed are the undefiled in the way, who walk in the law
    ('canon','psalms',119,1,'canon','psalms',1,2,'free',
      E'*But his delight is in the law of Yahuah (LORD); and in his law doth he meditate day and night* (Psalm 1:2). *Blessed are the undefiled in the way, who walk in the law of Yahuah (LORD)* (Psalm 119:1): the whole acrostic opens where the psalter opens — the blessed man is the one whose delight is the Torah, meditated day and night and walked in; the two psalms set the same two ways before us.'),
    ('canon','psalms',119,1,'canon','deuteronomy',28,1,'free',
      E'*And it shall come to pass, if thou shalt hearken diligently unto the voice of Yahuah Elohayka (the LORD thy God), to observe and to do all his commandments which I command thee this day, that Yahuah Elohayka (the LORD thy God) will set thee on high above all nations of the earth* (Deuteronomy 28:1). *Blessed are the undefiled in the way, who walk in the law of Yahuah (LORD)* (Psalm 119:1): the blessing is the covenant blessing of Deuteronomy — to walk in the law is to hearken and do all His commandments; the undefiled way is the way of obedience, not of the Torah set aside.'),
    ('canon','psalms',119,2,'canon','matthew',5,6,'free',
      E'*Blessed are they which do hunger and thirst after righteousness: for they shall be filled* (Matthew 5:6). *Blessed are they that keep his testimonies, and that seek him with the whole heart* (Psalm 119:2): the Messiah opens His own teaching with the same beatitude — the blessed are they who hunger for righteousness and seek Him with the whole heart; the keeping of the testimonies is the seeking that is filled.'),
    ('canon','psalms',119,1,'canon','1-john',2,3,'free',
      E'*And hereby we do know that we know him, if we keep his commandments* (1 John 2:3). *Blessed are the undefiled in the way, who walk in the law of Yahuah (LORD)* (Psalm 119:1): John gives the filter the whole acrostic embodies — to know Him is to keep His commandments; the undefiled walk in the law is the proof of the knowing, and *He that saith, I know him, and keepeth not his commandments, is a liar* (1 John 2:4).'),

    -- THREAD 2: Thy word have I hid in mine heart, that I might not sin
    ('canon','psalms',119,11,'canon','deuteronomy',6,6,'free',
      E'*And these words, which I command thee this day, shall be in thine heart* (Deuteronomy 6:6). *Thy word have I hid in mine heart, that I might not sin against thee* (Psalm 119:11): the psalmist does the very thing the Shema commands — the words of Yahuah laid up in the heart; the word hidden within is the safeguard against sin, the Deuteronomy charge kept inwardly.'),
    ('canon','psalms',119,9,'canon','jeremiah',15,16,'free',
      E'*Thy words were found, and I did eat them; and thy word was unto me the joy and rejoicing of mine heart: for I am called by thy name, O Yahuah Elohim (LORD God) of hosts* (Jeremiah 15:16). *Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word* (Psalm 119:9): the prophet eats the word the psalmist takes heed to — the word taken in becomes the joy of the heart and the cleansing of the way; the same hunger for the davar of Yahuah.'),
    ('canon','psalms',119,11,'canon','matthew',4,4,'free',
      E'*But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of Elohim (God)* (Matthew 4:4). *Thy word have I hid in mine heart, that I might not sin against thee* (Psalm 119:11): the Messiah, tempted, lives by the very word the psalmist hid in his heart — the word of Yahuah is the bread of the inward man, the defence against sin in the wilderness.'),

    -- THREAD 3: Open thou mine eyes — the entrance of thy words giveth light
    ('canon','psalms',119,18,'canon','luke',24,45,'free',
      E'*Then opened he their understanding, that they might understand the scriptures* (Luke 24:45). *Open thou mine eyes, that I may behold wondrous things out of thy law* (Psalm 119:18): the prayer of the psalmist is answered in the risen Messiah — He opens the understanding to behold the wondrous things out of the law, the prophets, and the psalms, *beginning at Moses and all the prophets* (Luke 24:27); the eyes opened to the Torah are opened by Him.'),
    ('canon','psalms',119,18,'canon','2-corinthians',3,14,'free',
      E'*But their minds were blinded: for until this day remaineth the same vail untaken away in the reading of the old testament; which vail is done away in Messiah (Christ)* (2 Corinthians 3:14). *Open thou mine eyes, that I may behold wondrous things out of thy law* (Psalm 119:18): mark what is done away — the VAIL on the reading, not the law read. *Nevertheless when it shall turn to Yahuah (Lord), the vail shall be taken away* (2 Corinthians 3:16): the same eyes the psalmist asks to be opened are unveiled in Messiah to behold the wondrous things of the very Torah.'),
    ('canon','psalms',119,130,'canon','1-corinthians',2,14,'free',
      E'*But the natural man receiveth not the things of the Spirit of Elohim (God): for they are foolishness unto him: neither can he know them, because they are spiritually discerned* (1 Corinthians 2:14). *The entrance of thy words giveth light; it giveth understanding unto the simple* (Psalm 119:130): the light of the word is spiritually given — the natural man cannot receive it, but the entrance of the words gives understanding to the simple whose eyes the Spirit opens; the Torah-light requires the opened eye of v.18.'),

    -- THREAD 4 (★★★ KEYSTONE): Enlarge my heart — the law written on the inward parts
    ('canon','psalms',119,32,'canon','jeremiah',31,33,'free',
      E'*But this shall be the covenant that I will make with the house of Yashar''el (Israel); After those days, saith Yahuah (LORD), I will put my law in their inward parts, and write it in their hearts; and will be their Elohim (God), and they shall be my people* (Jeremiah 31:33). *I will run the way of thy commandments, when thou shalt enlarge my heart* (Psalm 119:32): the psalmist''s prayer is the new covenant promised — the heart enlarged is the heart with the LAW written upon it; the new covenant is the SAME Torah put in the inward parts, never the Torah abolished.'),
    ('canon','psalms',119,36,'canon','ezekiel',36,26,'free',
      E'*A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh* (Ezekiel 36:26). *Incline my heart unto thy testimonies, and not to covetousness* (Psalm 119:36): the inclining the psalmist begs is the new heart Yahuah gives — the stony heart removed, the heart of flesh given, the heart turned toward the testimonies.'),
    ('canon','psalms',119,36,'canon','ezekiel',36,27,'free',
      E'*And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them* (Ezekiel 36:27). *Incline my heart unto thy testimonies* (Psalm 119:36): the very fruit of the new heart is walking in the statutes and keeping the judgments — the Spirit put within causes the obedience the psalmist longs for; the new covenant is unto the doing of the Torah, not its end.'),
    ('canon','psalms',119,34,'canon','2-corinthians',3,3,'free',
      E'*Forasmuch as ye are manifestly declared to be the epistle of Messiah (Christ) ministered by us, written not with ink, but with the Spirit of the living Elohim (God); not in tables of stone, but in fleshy tables of the heart* (2 Corinthians 3:3). *Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart* (Psalm 119:34): the law kept with the whole heart is the law written on the fleshy tables of the heart by the Spirit — the same Torah, moved from stone to the inward man.'),
    ('canon','psalms',119,32,'apocrypha','ecclesiasticus',24,23,'extras',
      E'*All these things are the book of the covenant of the most high Yahuah (God), even the law which Moses commanded for an heritage to the congregations of Jacob* (Sirach 24:23). *I will run the way of thy commandments, when thou shalt enlarge my heart* (Psalm 119:32): the restored wisdom names what dwells in the enlarged heart — the Wisdom that took root in Jacob IS the book of the covenant, the law Moses commanded; to run the way of the commandments is to run in Wisdom herself.'),

    -- THREAD 5: I will walk at liberty — the perfect law of liberty
    ('canon','psalms',119,45,'canon','james',1,25,'free',
      E'*But whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed* (James 1:25). *And I will walk at liberty: for I seek thy precepts* (Psalm 119:45): James names the Torah exactly as the psalmist knows it — the PERFECT LAW OF LIBERTY; the seeking of the precepts is the walking at liberty, freedom found in the law kept, not freedom from it.'),
    ('canon','psalms',119,45,'canon','james',2,12,'free',
      E'*So speak ye, and so do, as they that shall be judged by the law of liberty* (James 2:12). *And I will walk at liberty: for I seek thy precepts* (Psalm 119:45): the law is liberty and the law is the standard of judgment together — the very Torah the psalmist walks in at liberty is the law of liberty by which all are judged; the antinomian inversion is overturned.'),
    ('canon','psalms',119,45,'canon','john',8,32,'free',
      E'*And ye shall know the truth, and the truth shall make you free* (John 8:32). *And I will walk at liberty: for I seek thy precepts* (Psalm 119:45): the truth that frees is His word continued in — *If ye continue in my word, then are ye my disciples indeed* (John 8:31), *If the Son therefore shall make you free, ye shall be free indeed* (John 8:36); the liberty of the psalmist and the freedom of the Son are one, the bondage broken being the bondage to sin, not to the Torah.'),

    -- THREAD 6 (★★): Thy word is settled in heaven for ever
    ('canon','psalms',119,89,'canon','matthew',5,18,'free',
      E'*For verily I say unto you, Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled* (Matthew 5:18). *For ever, O Yahuah (LORD), thy word is settled in heaven* (Psalm 119:89): the Messiah seals the psalmist''s confession — the word settled in heaven cannot pass; not one jot or tittle of the law shall fail, *Think not that I am come to destroy the law* (Matthew 5:17). The eternal word is the abiding Torah.'),
    ('canon','psalms',119,160,'canon','isaiah',40,8,'free',
      E'*The grass withereth, the flower fadeth: but the word of our Elohim (God) shall stand for ever* (Isaiah 40:8). *Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever* (Psalm 119:160): the prophet sings what the psalmist confesses — all flesh is grass that withers, but the word of our Elohim stands for ever; the righteous judgments that endure are the standing word.'),
    ('canon','psalms',119,160,'canon','1-peter',1,25,'free',
      E'*But the word of Yahuah (Lord) endureth for ever. And this is the word which by the gospel is preached unto you* (1 Peter 1:25). *Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever* (Psalm 119:160): Peter takes up Isaiah''s witness and names the enduring word the very word preached — the davar that is true from the beginning is the davar that abides for ever, unchanging.'),
    ('canon','psalms',119,89,'canon','psalms',111,7,'free',
      E'*The works of his hands are verity and judgment; all his commandments are sure. They stand fast for ever and ever, and are done in truth and uprightness* (Psalm 111:7-8). *For ever, O Yahuah (LORD), thy word is settled in heaven* (Psalm 119:89): the companion psalm says the same of the commandments — they stand fast for ever and ever; the word settled in heaven and the commandments standing fast are one eternal covenant-word.'),
    ('canon','psalms',119,89,'apocrypha','baruch-with-the-letter-of-jeremiah',4,1,'extras',
      E'*This is the book of the commandments of Yahuah (God), and the law that endureth for ever: all they that keep it shall come to life; but such as leave it shall die* (Baruch 4:1). *For ever, O Yahuah (LORD), thy word is settled in heaven* (Psalm 119:89): the restored witness names the settled word the LAW THAT ENDURETH FOR EVER — they that keep it come to life, they that leave it die; the eternal word is the living covenant, not a covenant passed away.'),

    -- THREAD 7 (★★): O how love I thy law — sweeter than honey
    ('canon','psalms',119,97,'canon','romans',7,22,'free',
      E'*For I delight in the law of Elohim (God) after the inward man* (Romans 7:22). *O how love I thy law! it is my meditation all the day* (Psalm 119:97): Paul confesses the psalmist''s very love — the delight in the law of Elohim after the inward man; the meditation all the day and the inward delight are the same love of the Torah, written by the same hand of the Spirit.'),
    ('canon','psalms',119,97,'canon','romans',7,12,'free',
      E'*Wherefore the law is holy, and the commandment holy, and just, and good* (Romans 7:12). *O how love I thy law! it is my meditation all the day* (Psalm 119:97): the reason the psalmist loves the law is the reason Paul names — the law is holy, and the commandment holy, and just, and good; the thing loved is not a burden cast off but the good and holy Torah.'),
    ('canon','psalms',119,103,'canon','psalms',19,10,'free',
      E'*More to be desired are they than gold, yea, than much fine gold: sweeter also than honey and the honeycomb* (Psalm 19:10). *How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!* (Psalm 119:103): the companion psalm tastes the same sweetness — the words of Yahuah sweeter than honey and more to be desired than fine gold; the love of v.103 and v.127 (*I love thy commandments above gold*) is the delight Psalm 19 already sang.'),

    -- THREAD 8 (★★★): Thy word is a lamp unto my feet
    ('canon','psalms',119,105,'canon','proverbs',6,23,'free',
      E'*For the commandment is a lamp; and the law is light; and reproofs of instruction are the way of life* (Proverbs 6:23). *Thy word is a lamp unto my feet, and a light unto my path* (Psalm 119:105): the proverb says it plainly — the commandment is a lamp and the law is light; the word that lights the psalmist''s path is the Torah itself, the lamp for the feet and the light for the way of life.'),
    ('canon','psalms',119,105,'canon','psalms',19,8,'free',
      E'*The statutes of Yahuah (LORD) are right, rejoicing the heart: the commandment of Yahuah (LORD) is pure, enlightening the eyes* (Psalm 19:8). *Thy word is a lamp unto my feet, and a light unto my path* (Psalm 119:105): the commandment that enlightens the eyes is the lamp that lights the feet — the same illuminating Torah, rejoicing the heart and lighting the path.'),
    ('canon','psalms',119,105,'canon','2-peter',1,19,'free',
      E'*We have also a more sure word of prophecy; whereunto ye do well that ye take heed, as unto a light that shineth in a dark place, until the day dawn, and the day star arise in your hearts* (2 Peter 1:19). *Thy word is a lamp unto my feet, and a light unto my path* (Psalm 119:105): Peter names the word a light shining in a dark place — the lamp the psalmist walks by is the sure word of prophecy, taken heed to until the day dawns.'),
    ('canon','psalms',119,105,'canon','john',8,12,'free',
      E'*Then spake Yahusha (Jesus) again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life* (John 8:12). *Thy word is a lamp unto my feet, and a light unto my path* (Psalm 119:105): the Formed Son IS the light the word shed — the Word made flesh who embodies the Torah-light; he that follows Him walks not in darkness, for the lamp unto the feet is the One who is the light of the world.'),

    -- THREAD 9 (★★): Thy law is the truth
    ('canon','psalms',119,142,'canon','john',17,17,'free',
      E'*Sanctify them through thy truth: thy word is truth* (John 17:17). *Thy righteousness is an everlasting righteousness, and thy law is the truth* (Psalm 119:142): the Messiah prays the psalmist''s confession — the word is truth, and by that truth His own are sanctified; the law that is the truth (v.142), the commandments that are truth (v.151), the word true from the beginning (v.160) — all one truth that sanctifies.'),
    ('canon','psalms',119,151,'canon','psalms',19,9,'free',
      E'*The fear of Yahuah (LORD) is clean, enduring for ever: the judgments of Yahuah (LORD) are true and righteous altogether* (Psalm 19:9). *Thou art near, O Yahuah (LORD); and all thy commandments are truth* (Psalm 119:151): the companion psalm says the judgments are true and righteous altogether — the commandments that are truth and the judgments true and righteous are the same trustworthy Torah, enduring for ever.'),

    -- THREAD 10 (★★): Great peace have they which love thy law
    ('canon','psalms',119,165,'canon','proverbs',3,2,'free',
      E'*For length of days, and long life, and peace, shall they add to thee* (Proverbs 3:2). *Great peace have they which love thy law: and nothing shall offend them* (Psalm 119:165): the proverb promises peace to them that keep the commandment — *My son, forget not my law; but let thine heart keep my commandments* (Proverbs 3:1); the great peace of the Torah-lover is the peace the law adds to its keeper.'),
    ('canon','psalms',119,165,'canon','isaiah',32,17,'free',
      E'*And the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever* (Isaiah 32:17). *Great peace have they which love thy law: and nothing shall offend them* (Psalm 119:165): the prophet names the fruit of righteousness peace — the work of the Torah-keeping life is peace and quietness and assurance for ever, the very peace the psalmist enjoys, with nothing to make him stumble.'),
    ('canon','psalms',119,165,'canon','1-john',2,10,'free',
      E'*He that loveth his brother abideth in the light, and there is none occasion of stumbling in him* (1 John 2:10). *Great peace have they which love thy law: and nothing shall offend them* (Psalm 119:165): the love that keeps the commandments leaves no occasion of stumbling — the *nothing shall offend them* of the psalm is the *none occasion of stumbling* of John; the law loved removes the snare.'),
    ('canon','psalms',119,165,'canon','john',16,33,'free',
      E'*These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world* (John 16:33). *Great peace have they which love thy law: and nothing shall offend them* (Psalm 119:165): the great peace of the law-lover is the peace the Messiah gives — peace in Him in the midst of tribulation, the unoffended heart that the world cannot make to stumble.'),

    -- THREAD 11 (★★★): I have gone astray like a lost sheep
    ('canon','psalms',119,176,'canon','isaiah',53,6,'free',
      E'*All we like sheep have gone astray; we have turned every one to his own way; and Yahuah (LORD) hath laid on him the iniquity of us all* (Isaiah 53:6). *I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (Psalm 119:176): the closing confession is Isaiah''s — all like sheep gone astray; yet the iniquity is laid on the suffering servant, and the straying sheep who has not forgotten the commandments is sought and borne.'),
    ('canon','psalms',119,176,'canon','ezekiel',34,11,'free',
      E'*For thus saith Adonai Yahuah (the Lord GOD); Behold, I, even I, will both search my sheep, and seek them out* (Ezekiel 34:11). *I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (Psalm 119:176): the psalmist''s cry *seek thy servant* is answered by the Shepherd who Himself seeks — *I will seek that which was lost, and bring again that which was driven away* (Ezekiel 34:16); the two-house flock scattered is gathered by the one Shepherd, *my servant David* (Ezekiel 34:23).'),
    ('canon','psalms',119,176,'canon','luke',15,4,'free',
      E'*What man of you, having an hundred sheep, if he lose one of them, doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?* (Luke 15:4). *I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (Psalm 119:176): the Messiah tells the parable the psalm cries for — the lost sheep sought until found and laid on the shoulders rejoicing (Luke 15:5); the *seek thy servant* of the Torah-lover is the seeking love of the Shepherd.'),
    ('canon','psalms',119,176,'canon','matthew',18,12,'free',
      E'*How think ye? if a man have an hundred sheep, and one of them be gone astray, doth he not leave the ninety and nine, and goeth into the mountains, and seeketh that which is gone astray?* (Matthew 18:12). *I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (Psalm 119:176): the gone-astray sheep is sought into the mountains — *the Son of Adam is come to save that which was lost* (Matthew 18:11); it is not the will of the Father that one of these little ones should perish, and so the straying servant is sought.'),

    -- THREAD 12: Before I was afflicted I went astray — that I might learn thy statutes
    ('canon','psalms',119,71,'canon','psalms',94,12,'free',
      E'*Blessed is the man whom thou chastenest, O Yahuah (LORD), and teachest him out of thy law* (Psalm 94:12). *It is good for me that I have been afflicted; that I might learn thy statutes* (Psalm 119:71): the companion psalm names the blessing exactly — the chastened man is taught out of the law; the affliction that the psalmist calls good is the teaching of the statutes, the discipline that schools in the Torah.'),
    ('canon','psalms',119,75,'canon','deuteronomy',8,5,'free',
      E'*Thou shalt also consider in thine heart, that, as a man chasteneth his son, so Yahuah Elohayka (the LORD thy God) chasteneth thee* (Deuteronomy 8:5). *I know, O Yahuah (LORD), that thy judgments are right, and that thou in faithfulness hast afflicted me* (Psalm 119:75): the faithful affliction is the Father''s chastening of the son — Yahuah humbling and proving in the wilderness to know what is in the heart, *whether thou wouldest keep his commandments, or no* (Deuteronomy 8:2); the right judgments afflict in faithfulness, unto obedience.'),
    ('canon','psalms',119,67,'canon','hebrews',12,11,'free',
      E'*Now no chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby* (Hebrews 12:11). *Before I was afflicted I went astray: but now have I kept thy word* (Psalm 119:67): the chastening that turned the psalmist from straying to keeping the word is the discipline Hebrews names — grievous for the present, but yielding afterward the peaceable fruit of righteousness; the affliction is the Father correcting the son He receives.')
  ) AS i(src_edition,src_slug,src_ch,src_v,tgt_edition,tgt_slug,tgt_ch,tgt_v,tier,note)
  JOIN _s302_ps119_lookup sv ON sv.edition_slug=i.src_edition AND sv.book_slug=i.src_slug AND sv.chapter_number=i.src_ch AND sv.verse_number=i.src_v
  JOIN _s302_ps119_lookup tv ON tv.edition_slug=i.tgt_edition AND tv.book_slug=i.tgt_slug AND tv.chapter_number=i.tgt_ch AND tv.verse_number=i.tgt_v
 WHERE sv.verse_id <> tv.verse_id
ON CONFLICT (source_verse_id, target_verse_id, source) DO NOTHING;

-- THREAD 1
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-blessed-are-the-undefiled-who-walk-in-the-law',
       E'Blessed are the undefiled in the way, who walk in the law',
       E'The longest chapter in Scripture opens with a beatitude on the Torah-keeper: *Blessed are the undefiled in the way, who walk in the law of Yahuah (LORD). Blessed are they that keep his testimonies, and that seek him with the whole heart. They also do no iniquity: they walk in his ways* (Psalm 119:1-3). This is exactly where the whole psalter opens — *Blessed is the man... but his delight is in the law of Yahuah (LORD); and in his law doth he meditate day and night* (Psalm 1:1-2) — and exactly the covenant blessing of Moses: *if thou shalt hearken diligently unto the voice of Yahuah Elohayka (the LORD thy God), to observe and to do all his commandments... that Yahuah Elohayka (the LORD thy God) will set thee on high* (Deuteronomy 28:1). The Messiah takes up the same beatitude: *Blessed are they which do hunger and thirst after righteousness: for they shall be filled* (Matthew 5:6). And John gives the filter the entire acrostic embodies: *hereby we do know that we know him, if we keep his commandments. He that saith, I know him, and keepeth not his commandments, is a liar, and the truth is not in him* (1 John 2:3-4). To walk undefiled in the law is to seek Him with the whole heart — the blessedness is the obedience, not the law set aside.',
       sv.verse_id, ev.verse_id, 'free', 24950
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=1
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=3
ON CONFLICT (slug) DO NOTHING;

-- THREAD 2
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-thy-word-have-i-hid-in-mine-heart',
       E'Thy word have I hid in mine heart, that I might not sin',
       E'The Beth stanza asks and answers how a life is cleansed: *Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word. With my whole heart have I sought thee: O let me not wander from thy commandments. Thy word have I hid in mine heart, that I might not sin against thee* (Psalm 119:9-11). This is the Shema obeyed inwardly: *these words, which I command thee this day, shall be in thine heart* (Deuteronomy 6:6). The prophet does the same and finds joy: *Thy words were found, and I did eat them; and thy word was unto me the joy and rejoicing of mine heart* (Jeremiah 15:16). And the Messiah Himself, tempted in the wilderness, lives by the word the psalmist hid: *It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of Elohim (God)* (Matthew 4:4). The word hidden in the heart is the safeguard against sin and the bread of the inward man.',
       sv.verse_id, ev.verse_id, 'free', 24953
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=9
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=11
ON CONFLICT (slug) DO NOTHING;

-- THREAD 3
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-open-thou-mine-eyes-the-entrance-of-thy-words-giveth-light',
       E'Open thou mine eyes — the entrance of thy words giveth light',
       E'The psalmist prays for sight into the Torah: *Open thou mine eyes, that I may behold wondrous things out of thy law* (Psalm 119:18); and confesses how the word illuminates: *The entrance of thy words giveth light; it giveth understanding unto the simple* (Psalm 119:130). This is the prayer the risen Messiah answers: *Then opened he their understanding, that they might understand the scriptures* (Luke 24:45), *beginning at Moses and all the prophets* (Luke 24:27). And Paul reads the veil exactly: it is the VAIL on the reading that is done away, not the law read — *until this day remaineth the same vail untaken away in the reading of the old testament; which vail is done away in Messiah (Christ)... when it shall turn to Yahuah (Lord), the vail shall be taken away* (2 Corinthians 3:14-16). The light is spiritually given: *the natural man receiveth not the things of the Spirit of Elohim (God)... because they are spiritually discerned* (1 Corinthians 2:14). The eyes are opened to the SAME Torah — the wondrous things were always there; the Spirit unveils them.',
       sv.verse_id, ev.verse_id, 'free', 24956
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=18
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=130
ON CONFLICT (slug) DO NOTHING;

-- THREAD 4 (★★★ KEYSTONE)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-enlarge-my-heart-the-law-written-on-the-inward-parts',
       E'Enlarge my heart — the law written on the inward parts',
       E'The He stanza prays for the very heart the new covenant promises: *I will run the way of thy commandments, when thou shalt enlarge my heart* (Psalm 119:32); *Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart* (Psalm 119:34); *Incline my heart unto thy testimonies, and not to covetousness* (Psalm 119:36). This is the prayer Jeremiah and Ezekiel answer. *I will put my law in their inward parts, and write it in their hearts; and will be their Elohim (God), and they shall be my people* (Jeremiah 31:33): the new covenant is the SAME Torah moved into the heart, never the Torah abolished. *A new heart also will I give you... and I will take away the stony heart out of your flesh, and I will give you an heart of flesh. And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them* (Ezekiel 36:26-27): the new heart is unto walking in the statutes. Paul names the tablet: *written not with ink, but with the Spirit of the living Elohim (God); not in tables of stone, but in fleshy tables of the heart* (2 Corinthians 3:3). And the restored wisdom names what dwells in the enlarged heart: *All these things are the book of the covenant of the most high Yahuah (God), even the law which Moses commanded for an heritage to the congregations of Jacob* (Sirach 24:23). To run the way of the commandments with an enlarged heart is to keep the law written within by the Spirit.',
       sv.verse_id, ev.verse_id, 'extras', 24959
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=32
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=36
ON CONFLICT (slug) DO NOTHING;

-- THREAD 5 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-i-will-walk-at-liberty-the-perfect-law-of-liberty',
       E'I will walk at liberty — the perfect law of liberty',
       E'The antinomian inversion — that the law is bondage and freedom lies in leaving it — is overturned in a single line: *And I will walk at liberty: for I seek thy precepts* (Psalm 119:45). Liberty is found IN the precepts sought, not apart from them. James names the Torah exactly this way: *whoso looketh into the perfect law of liberty, and continueth therein, he being not a forgetful hearer, but a doer of the work, this man shall be blessed in his deed* (James 1:25); *So speak ye, and so do, as they that shall be judged by the law of liberty* (James 2:12) — the law is both liberty and the standard of judgment. And the Son names the freedom: *If ye continue in my word, then are ye my disciples indeed; And ye shall know the truth, and the truth shall make you free* (John 8:31-32); *If the Son therefore shall make you free, ye shall be free indeed* (John 8:36). The bondage broken is the bondage to sin (*Whosoever committeth sin is the servant of sin*, John 8:34), never the bondage to the Torah. Freedom IS Torah-keeping.',
       sv.verse_id, ev.verse_id, 'free', 24962
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=45
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=45
ON CONFLICT (slug) DO NOTHING;

-- THREAD 6 (★★ anti-antinomian keystone)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-thy-word-is-settled-in-heaven-for-ever',
       E'For ever, O Yahuah, thy word is settled in heaven',
       E'The Lamed stanza lifts the eyes to the eternal, unchanging word: *For ever, O Yahuah (LORD), thy word is settled in heaven* (Psalm 119:89); and the Schin stanza seals it: *Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever* (Psalm 119:160), as the psalmist had already known *of old that thou hast founded them for ever* (Psalm 119:152). This is the anti-antinomian keystone. The Messiah seals it: *Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled* (Matthew 5:18) — and *Think not that I am come to destroy the law* (Matthew 5:17). The prophet sings it: *The grass withereth, the flower fadeth: but the word of our Elohim (God) shall stand for ever* (Isaiah 40:8), which Peter takes up — *the word of Yahuah (Lord) endureth for ever* (1 Peter 1:25). The companion psalm says it of the commandments: *all his commandments are sure. They stand fast for ever and ever, and are done in truth and uprightness* (Psalm 111:7-8). And the restored witness names the settled word: *This is the book of the commandments of Yahuah (God), and the law that endureth for ever* (Baruch 4:1). The word settled in heaven is the abiding Torah — not one jot of it shall pass.',
       sv.verse_id, ev.verse_id, 'extras', 24965
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=89
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=160
ON CONFLICT (slug) DO NOTHING;

-- THREAD 7 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-o-how-love-i-thy-law-sweeter-than-honey',
       E'O how love I thy law — sweeter than honey',
       E'The Mem stanza pours out the delight that runs the whole acrostic: *O how love I thy law! it is my meditation all the day* (Psalm 119:97); and the taste of it: *How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!* (Psalm 119:103); the love above riches: *Therefore I love thy commandments above gold; yea, above fine gold* (Psalm 119:127); the love against falsehood: *I hate vain thoughts: but thy law do I love* (Psalm 119:113); the exceeding love: *My soul hath kept thy testimonies; and I love them exceedingly* (Psalm 119:167). Paul confesses the very same love: *For I delight in the law of Elohim (God) after the inward man* (Romans 7:22) — for *the law is holy, and the commandment holy, and just, and good* (Romans 7:12). And the companion psalm tasted the sweetness first: *More to be desired are they than gold, yea, than much fine gold: sweeter also than honey and the honeycomb* (Psalm 19:10). The Torah loved is no burden cast off; it is the good and holy delight of the inward man.',
       sv.verse_id, ev.verse_id, 'free', 24968
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=97
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=103
ON CONFLICT (slug) DO NOTHING;

-- THREAD 8 (★★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-thy-word-is-a-lamp-unto-my-feet',
       E'Thy word is a lamp unto my feet, and a light unto my path',
       E'The most loved verse of the acrostic makes the word the light to walk by: *Thy word is a lamp unto my feet, and a light unto my path* (Psalm 119:105). The proverb says it plainly: *For the commandment is a lamp; and the law is light; and reproofs of instruction are the way of life* (Proverbs 6:23) — the lamp IS the commandment, the light IS the law. The companion psalm names the same: *the commandment of Yahuah (LORD) is pure, enlightening the eyes* (Psalm 19:8). Peter calls the word *a light that shineth in a dark place, until the day dawn, and the day star arise in your hearts* (2 Peter 1:19). And the Formed Son embodies the Torah-light Himself: *I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life* (John 8:12). The lamp unto the feet is the Word who is the light of the world; to walk by the Torah is to walk by Him.',
       sv.verse_id, ev.verse_id, 'free', 24971
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=105
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=105
ON CONFLICT (slug) DO NOTHING;

-- THREAD 9 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-thy-law-is-the-truth',
       E'Thy law is the truth — all thy commandments are truth',
       E'Three times across the closing stanzas the psalmist confesses the Torah to be truth itself: *Thy righteousness is an everlasting righteousness, and thy law is the truth* (Psalm 119:142); *Thou art near, O Yahuah (LORD); and all thy commandments are truth* (Psalm 119:151); *Thy word is true from the beginning* (Psalm 119:160). The Messiah prays this very confession over His own: *Sanctify them through thy truth: thy word is truth* (John 17:17) — His own are made holy by the word that is truth. And the companion psalm says the same of the judgments: *the judgments of Yahuah (LORD) are true and righteous altogether* (Psalm 19:9). The law is not a passing shadow but the standing truth by which the saints are sanctified.',
       sv.verse_id, ev.verse_id, 'free', 24974
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=142
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=160
ON CONFLICT (slug) DO NOTHING;

-- THREAD 10 (★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-great-peace-have-they-which-love-thy-law',
       E'Great peace have they which love thy law',
       E'Near the close the psalmist names the fruit of the loved Torah: *Great peace have they which love thy law: and nothing shall offend them* (Psalm 119:165). The proverb promises that peace to the keeper of the commandment: *My son, forget not my law; but let thine heart keep my commandments: For length of days, and long life, and peace, shall they add to thee* (Proverbs 3:1-2). The prophet names it the very effect of righteousness: *the work of righteousness shall be peace; and the effect of righteousness quietness and assurance for ever* (Isaiah 32:17). John names the unoffended heart: *He that loveth his brother abideth in the light, and there is none occasion of stumbling in him* (1 John 2:10) — the *nothing shall offend them* of the psalm. And the Messiah gives the peace itself: *in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world* (John 16:33). The law loved leaves no stumbling-block; great peace is the portion of its lovers.',
       sv.verse_id, ev.verse_id, 'free', 24977
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=165
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=165
ON CONFLICT (slug) DO NOTHING;

-- THREAD 11 (★★★)
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-i-have-gone-astray-like-a-lost-sheep',
       E'I have gone astray like a lost sheep — seek thy servant',
       E'After 175 verses exalting the Torah, the great acrostic closes not in triumph but in humble confession — and still holding the commandments: *I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments* (Psalm 119:176). This is Isaiah''s confession of us all: *All we like sheep have gone astray; we have turned every one to his own way; and Yahuah (LORD) hath laid on him the iniquity of us all* (Isaiah 53:6). And the cry *seek thy servant* is answered by the Shepherd who Himself goes seeking: *Behold, I, even I, will both search my sheep, and seek them out... I will seek that which was lost, and bring again that which was driven away* (Ezekiel 34:11,16) — the scattered two-house flock gathered by *one shepherd... my servant David* (Ezekiel 34:23). The Messiah tells the parable the psalm cries for: *doth not leave the ninety and nine in the wilderness, and go after that which is lost, until he find it?* (Luke 15:4), and *the Son of Adam is come to save that which was lost* (Matthew 18:11-12). The Torah-lover still strays — and is sought, found, and carried home.',
       sv.verse_id, ev.verse_id, 'free', 24980
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=176
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=176
ON CONFLICT (slug) DO NOTHING;

-- THREAD 12
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'psalm-119-before-i-was-afflicted-i-went-astray-that-i-might-learn-thy-statutes',
       E'Before I was afflicted I went astray — that I might learn thy statutes',
       E'The Teth stanza turns affliction into the schoolroom of the Torah: *Before I was afflicted I went astray: but now have I kept thy word* (Psalm 119:67); *It is good for me that I have been afflicted; that I might learn thy statutes* (Psalm 119:71); *I know, O Yahuah (LORD), that thy judgments are right, and that thou in faithfulness hast afflicted me* (Psalm 119:75). The companion psalm names the blessing exactly: *Blessed is the man whom thou chastenest, O Yahuah (LORD), and teachest him out of thy law* (Psalm 94:12). Moses names the Father''s purpose in it: *as a man chasteneth his son, so Yahuah Elohayka (the LORD thy God) chasteneth thee* (Deuteronomy 8:5), humbling and proving *whether thou wouldest keep his commandments, or no* (Deuteronomy 8:2). And Hebrews names the fruit: *no chastening for the present seemeth to be joyous, but grievous: nevertheless afterward it yieldeth the peaceable fruit of righteousness unto them which are exercised thereby* (Hebrews 12:11). The affliction is the Father correcting the son He receives — and it drives the straying heart back to the statutes.',
       sv.verse_id, ev.verse_id, 'free', 24983
  FROM _s302_ps119_lookup sv, _s302_ps119_lookup ev
 WHERE sv.edition_slug='canon' AND sv.book_slug='psalms' AND sv.chapter_number=119 AND sv.verse_number=67
   AND ev.edition_slug='canon' AND ev.book_slug='psalms' AND ev.chapter_number=119 AND ev.verse_number=75
ON CONFLICT (slug) DO NOTHING;

